from pathlib import Path
from typing import Any
from typing import TextIO
import csv
import io

REQUIRED_COLUMNS = ('name', 'email')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254
EXCEL_SUFFIXES = ('.xlsx', '.xlsm')


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def _cell_to_text(value: Any) -> str:
    if value is None:
        return ''
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    # Newlines would shift CSV line numbers away from spreadsheet row numbers.
    return str(value).replace('\r', ' ').replace('\n', ' ')


def excel_to_csv_text(path: Path) -> str:
    """Convert the first sheet to CSV text, keeping 1 spreadsheet row == 1 CSV line."""
    from openpyxl import load_workbook

    workbook = load_workbook(path, read_only=True, data_only=True)
    try:
        sheet = workbook.worksheets[0]
        out = io.StringIO(newline='')
        writer = csv.writer(out, lineterminator='\n')
        for cells in sheet.iter_rows(values_only=True):
            texts = [_cell_to_text(c) for c in cells]
            # Fully blank rows become empty lines (skipped by the parser, numbering preserved).
            writer.writerow(texts if any(t.strip() for t in texts) else [])
        return out.getvalue()
    finally:
        workbook.close()


def read_spreadsheet_text(path: str | Path) -> str:
    path = Path(path)
    suffix = path.suffix.lower()
    if suffix in EXCEL_SUFFIXES:
        return excel_to_csv_text(path)
    if suffix in ('.csv', '.txt', ''):
        return path.read_text(encoding='utf-8-sig')
    raise ValueError(f'unsupported file type: {suffix} (use .csv, .xlsx or .xlsm)')


def validate_users_upload(path: str | Path, max_rows: int=MAX_ROWS) -> dict[str, Any]:
    """Validate an uploaded users spreadsheet (CSV or Excel).

    Never stops at the first problem: every invalid row is reported with its
    row number (header is row 1) and all reasons it failed. Cell values are
    not echoed back in the report.

    Returns:
        {"ok": bool, "total_rows": int, "valid_count": int, "invalid_count": int,
         "valid_users": [...], "invalid_rows": [{"row": int, "errors": [str, ...]}]}
    """
    try:
        text = read_spreadsheet_text(path)
    except (OSError, ValueError, UnicodeDecodeError) as exc:
        return {
            'ok': False, 'total_rows': 0, 'valid_count': 0, 'invalid_count': 1,
            'valid_users': [],
            'invalid_rows': [{'row': 0, 'errors': [f'could not read file: {type(exc).__name__}']}],
        }
    except Exception as exc:  # corrupt/unreadable Excel workbooks raise library-specific errors
        return {
            'ok': False, 'total_rows': 0, 'valid_count': 0, 'invalid_count': 1,
            'valid_users': [],
            'invalid_rows': [{'row': 0, 'errors': [f'could not parse file: {type(exc).__name__}']}],
        }

    valid_users, errors = import_users(text, max_rows=max_rows)
    errors = sorted(errors, key=lambda e: e['row'])
    return {
        'ok': not errors,
        'total_rows': len(valid_users) + len(errors),
        'valid_count': len(valid_users),
        'invalid_count': len(errors),
        'valid_users': valid_users,
        'invalid_rows': errors,
    }

